from fastapi import FastAPI, Depends
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_bearer_token():
    # Test case 1: Single space (correct)
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    print(f"Case 1: {response.json()}")
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 2: Multiple spaces
    response = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    print(f"Case 2: {response.json()}")
    # Before fix, this should fail and be {"scheme": "Bearer", "credentials": "  xxx"}
    # assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

    # Test case 3: Trailing whitespace
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    print(f"Case 3: {response.json()}")
    # Before fix, this should fail and be {"scheme": "Bearer", "credentials": "xxx "}
    # assert response.json() == {"scheme": "Bearer", "credentials": "xxx "}

if __name__ == "__main__":
    try:
        test_bearer_token()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Tests failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

steps.message:
The bug was caused by `get_authorization_scheme_param` in `fastapi/security/utils.py` preserving leading and trailing whitespace in the extracted credential parameter of the `Authorization` header. This violated RFC 6750, where only the space between the scheme (e.g., "Bearer") and the token should be treated as a separator. I fixed this by adding `.strip()` to the returned credential parameter.

```python
def get_authorization_scheme_param(
    authorization_header_value: Optional[str],
) -> tuple[str, str]:
    if not authorization_header_value:
        return "", ""
    scheme, _, param = authorization_header_value.partition(" ")
    return scheme, param.strip()
```
